    /// </summary>
    [pbr::OriginalName("TEAM")] Team = 1,
    /// <summary>
    /// 公会频道
    /// </summary>
    [pbr::OriginalName("GUILD")] Guild = 2,
    /// <summary>
    /// 世界频道
    /// </summary>
    [pbr::OriginalName("WORLD")] World = 3,
  }

  /// <summary>
  /// Group member role
  /// </summary>
  public enum GroupMemberRole {
    /// <summary>
    /// Regular member
    /// </summary>
    [pbr::OriginalName("MEMBER")] Member = 0,
    /// <summary>
    /// Can kick/ban members
    /// </summary>
    [pbr::OriginalName("MODERATOR")] Moderator = 1,
    /// <summary>
    /// Full admin privileges
    /// </summary>
    [pbr::OriginalName("ADMIN")] Admin = 2,
    /// <summary>
    /// Group owner
    /// </summary>
    [pbr::OriginalName("OWNER")] Owner = 3,
  }

  /// <summary>
