    /// </summary>
    [pbr::OriginalName("CHANNEL_KIND_TEXT")] Text = 0,
    /// <summary>
    /// Voice channel
    /// </summary>
    [pbr::OriginalName("CHANNEL_KIND_VOICE")] Voice = 1,
    /// <summary>
    /// Announcement channel (admin only post)
    /// </summary>
    [pbr::OriginalName("CHANNEL_KIND_ANNOUNCEMENT")] Announcement = 2,
    /// <summary>
    /// Stage channel (for events)
    /// </summary>
    [pbr::OriginalName("CHANNEL_KIND_STAGE")] Stage = 3,
    /// <summary>
    /// Forum channel (threaded discussions)
    /// </summary>
    [pbr::OriginalName("CHANNEL_KIND_FORUM")] Forum = 4,
  }

  /// <summary>
  /// Channel permission override
  /// </summary>
  public enum PermissionType {
    /// <summary>
